INSERT INTO public.blitz_questions(topic,question,options,correct_index,legal_act,article,source_url,explanation,verified) VALUES
('Налоги: полномочия и элементы','В проекте закона субъекта предлагается новый налог, не предусмотренный Налоговым кодексом. Допустима ли такая конструкция?','["Да, при единогласном решении регионального парламента","Нет; перечень налогов и сборов определяется НК РФ","Да, если средства остаются в регионе","Да, по распоряжению губернатора"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Какие уровни налогов и сборов прямо предусматривает НК РФ?','["Общегосударственные и ведомственные","Обязательные и факультативные","Федеральные, региональные и местные","Федеральные и районные"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Может ли муниципалитет отменить установленный НК РФ федеральный налог на своей территории?','["Верно","Неверно"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Что делает региональный налог обязательным на территории субъекта в общем случае?','["Наличие согласия каждого налогоплательщика","Его установление НК РФ и законом субъекта, введение в установленном порядке","Публикация муниципальной программы","Решение областного отделения Банка России"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Могут ли города федерального значения устанавливать местные налоги своими законами в пределах НК РФ?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','У регионального налога закон субъекта определил ставку выше предела НК РФ. Как оценить решение?','["Законно, если парламент голосовал открыто","Допустимо только в столице субъекта","Недопустимо: региональная компетенция ограничена НК РФ","Всегда допускается при дефиците бюджета"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Может ли субъект РФ своим законом установить особенности определения базы регионального налога в пределах, предусмотренных НК РФ?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Кто определяет налогоплательщиков регионального налога согласно общему правилу НК РФ?','["Налоговый кодекс Российской Федерации","Муниципальная избирательная комиссия","Общественная палата субъекта","Главный распорядитель бюджета"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Допускает ли НК РФ специальные налоговые режимы, предусматривающие освобождение от отдельных налогов и сборов?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Какой акт отменяет федеральные, региональные и местные налоги и сборы?','["Распоряжение главы муниципалитета","Письмо налогового органа","Налоговый кодекс Российской Федерации","Постановление территориального суда"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая)','статья 12','https://www.consultant.ru/document/cons_doc_LAW_19671/ab54b1f6e016638e006428e90971b05636b17cbf/','Статья 12 НК РФ разграничивает виды налогов и полномочия по их введению.',true),
('Налоги: полномочия и элементы','Для признания налога установленным достаточно указать только налоговую ставку?','["Да","Нет"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Какая совокупность относится к обязательным элементам установления налога?','["Только налоговая ставка и санкции","Наименование министерства и адрес казначейства","Налогоплательщик, объект, база, период, ставка, порядок исчисления, порядок и сроки уплаты","Только адрес и организационная форма плательщика"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Должен ли акт, устанавливающий налог, определить объект налогообложения?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','В законопроекте указаны налогоплательщики, база и ставка, но не предусмотрен порядок исчисления. Полно ли установлен налог?','["Да, расчёт определит бухгалтерская служба","Нет; отсутствует обязательный элемент налогообложения","Да, если налог временный","Да, если ставка выражена процентом"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Для обычного периодического налога необходимо определить налоговый период?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Обязан ли законодатель устанавливать налоговую льготу для каждого нового налога?','["Да, для всех категорий","Нет; льготы предусматриваются при необходимости","Да, если налог федеральный","Да, если налог региональный"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Может ли налог считаться установленным без указания налогоплательщиков?','["Да","Нет"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Что необходимо определить при установлении сбора?','["Только срок действия политической программы","Плательщиков и элементы обложения применительно к конкретному сбору","Только форму бюджетного отчёта","Лишь ведомственный номер"]'::jsonb,1,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','Какой элемент налога отсутствует в перечне обязательных по статье 17 НК РФ?','["Налоговая база","Порядок исчисления","Размер административного штрафа за просрочку","Налоговая ставка"]'::jsonb,2,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true),
('Налоги: полномочия и элементы','При установлении разового налога требование об определении налогового периода имеет специальное исключение?','["Да","Нет"]'::jsonb,0,'Налоговый кодекс Российской Федерации (часть первая)','статья 17','https://www.consultant.ru/document/cons_doc_LAW_19671/27c48775695f5049e317dfe269ede10c3394b4ae/','Статья 17 НК РФ устанавливает обязательные элементы налогообложения и правило о льготах.',true)
